# ---------- docx ----------
d = Document(T); body = d.element.body
for el in list(body):
    if not el.tag.endswith('sectPr'): body.remove(el)
def runs(p, text):
    for i, part in enumerate(re.split(r'\*\*', text)):
        if part: r = p.add_run(part); r.bold = (i % 2 == 1)
d.add_heading(TITLE, 1)
for k, v in S:
    if k == 'h': d.add_heading(v, 3)
    elif k == 'p': runs(d.add_paragraph(), v)
    elif k == 'b':
        for t in v:
            p = d.add_paragraph(); p.add_run('• '); runs(p, t)
    elif k == 'img':
        d.add_paragraph().add_run().add_picture(v[0], width=Emu(5760000))
        r = d.add_paragraph().add_run(v[1]); r.font.size = Pt(9); r.font.color.rgb = RGBColor(0x5e, 0x61, 0x68)
    elif k == 't':
        t = d.add_table(rows=len(v), cols=2); t.style = 'Table Grid'
        for i, row in enumerate(v):
            for c, txt in zip(t.rows[i].cells, row):
                r = c.paragraphs[0].add_run(txt); r.bold = (i == 0)
d.core_properties.title = 'Хабр — ИИ-разработчик закрытого цикла (Даниил Пилипенко)'
d.core_properties.author = 'Даниил Пилипенко'
d.save(OUT)

# ---------- md ----------
M = [f'# {TITLE}', '', '*Даниил Пилипенко, SymbioWay*', '']
n = 0
for k, v in S:
    if k == 'h': M += [f'## {v}', '']
    elif k == 'p': M += [v, '']
    elif k == 'b': M += [f'- {t}' for t in v] + ['']
    elif k == 'img':
        n += 1; M += [f'![{v[1]}](схема-{n}.png)', '', f'*{v[1]}*', '']
    elif k == 't':
        M += ['| ' + ' | '.join(v[0]) + ' |', '|---|---|'] + ['| ' + ' | '.join(r) + ' |' for r in v[1:]] + ['']
open(f'{DIR}/Статья для Хабра (вставить в редактор).md', 'w').write('\n'.join(M))
plain = ' '.join(x if isinstance(x, str) else ' '.join(map(str, x)) for k, x in S if k in 'hpb').replace('**', '')
print('chars', len(plain) + len(TITLE))
